    if(!aggregate)return pageHead("Growth architecture","Career Path Configuration","Each Team owns an independent supported-growth graph and publication history.","",`<span class="chip">${esc(team?.name||"Team")}</span>${badge("Not configured")}`)+teamSwitcher+`<section class="empty-state career-team-empty"><div class="empty-icon">↗</div><h2>Create ${esc(team.name)}'s first Career Path</h2><p class="muted">Start an empty Working Draft, then add Positions using only Organization Roles enabled for this Team.</p><div class="cluster career-enabled-roles">${enabledRolesForTeam(teamId).map(role=>`<span class="chip">${esc(role.name)}</span>`).join("")||badge("No enabled Roles")}</div><button class="button primary" data-action="create-team-career-path" data-team="${teamId}">Create Working Draft</button></section>`;
