    return pageHead("Trust & traceability","Governance & Audit","Inspect who changed organizational structures, taxonomy, rating scales and framework versions — including before/after evidence and downstream impact.",`<button class="button" data-action="export-audit">Export visible log</button>`,`<span class="chip">Role · Level · Category · Scale · Framework</span>`)+
      `<div class="toolbar"><div class="field"><label>Object type</label><select id="audit-object">${["All governed objects","Framework","Rating Scale","Role / Level","Category"].map(value=>`<option ${value===auditFilters.object?"selected":""}>${value}</option>`).join("")}</select></div><div class="field"><label>Actor</label><select id="audit-actor">${["All actors","Tuyen Nguyen","Luc Tran"].map(value=>`<option ${value===auditFilters.actor?"selected":""}>${value}</option>`).join("")}</select></div><div class="field"><label>Date range</label><select id="audit-range">${["All history","Last 30 days"].map(value=>`<option ${value===auditFilters.range?"selected":""}>${value}</option>`).join("")}</select></div></div><section class="card pad"><div class="section-head"><div><h2>${visible.length} visible events</h2><p>Filters affect both this timeline and the exported CSV.</p></div></div><div class="timeline" id="audit-timeline">${visible.length?visible.map(a=>`<button class="timeline-item" data-action="audit-detail" data-audit="${a.id}" style="border:0;background:none;text-align:left;padding:0;cursor:pointer"><b>${esc(a.action)}</b><span class="meta">${esc(a.date)} · ${esc(a.actor)} · ${esc(a.object)}</span><p>${esc(a.impacted)}</p></button>`).join(""):`<div class="empty-state" style="padding:24px"><h3>No events match these filters</h3><p class="muted">Change object, actor or date range to widen the audit view.</p></div>`}</div></section>`;
