  function renderView() {
    const views = persona === "hr" ? {
      overview:hrOverview, teams:teamsView, users:usersView, roles:rolesView, library:libraryView, categories:categoriesView, "rating-scale":ratingScaleView,
      templates:templatesView, frameworks:frameworksView, career:careerConfigView, capability:capabilityView, audit:auditView
    } : persona === "manager" ? {
      "team-overview":teamOverview, "team-framework":teamFrameworkView, "team-competencies":teamCompetenciesView,
      "team-members":teamMembersView, assessments:assessmentsView, "assessment-requests":assessmentRequestsView,
      "development-plans":developmentPlansView, "learning-resources":learningResourcesView
    } : persona === "employee" ? {
      profile:profileView, "career-path":careerPathView, "my-assessments":myAssessmentsView,
      "my-requests":myRequestsView, "my-idp":myIdpView, notifications:notificationsView
    } : {
      "review-invitations":reviewerInvitationsView, "review-guidance":reviewerGuidanceView
    };
    const view=views[route]||views[personaConfig[persona].home];
    return view();
  }
  function render() { app.innerHTML=shell(renderView()); bindDragAndDrop(); flushPendingToast(); }
