    modal(team?`Configure ${team.name}`:"Create Team",`<form id="team-form" data-form="team"><input type="hidden" name="id" value="${esc(team?.id||"")}"><div class="form-grid"><div class="field full"><label>Team name</label><input name="name" required value="${esc(team?.name||"")}" placeholder="e.g. PDO"></div><div class="field full"><label>Description</label><textarea name="description" required>${esc(team?.description||"")}</textarea></div><div class="field"><label>Primary Manager</label><select name="managerId"><option value="">Not assigned yet</option>${managers.map(manager=>`<option value="${manager.id}" ${manager.id===team?.managerId?"selected":""}>${esc(manager.name)}</option>`).join("")}</select></div><div class="field"><label>Status</label><select name="status"><option ${team?.status!=="Archived"?"selected":""}>Active</option><option ${team?.status==="Archived"?"selected":""}>Archived</option></select></div><div class="field full"><label>Enabled Organization Roles</label><div class="role-check-grid">${state.roles.filter(role=>role.family!=="Administration").map(role=>`<label class="role-check"><input type="checkbox" name="enabledRoleIds" value="${role.id}" ${enabled.includes(role.id)?"checked":""}><span><b>${esc(role.name)}</b><small>${role.levels.map(level=>esc(level.name)).join(" · ")}</small></span></label>`).join("")}</div></div></div><div class="validation info" style="margin-top:14px"><b>Team is the organizational scope</b><p>Framework, Career Path, Members and Primary Manager are configured against this Team. No Department layer is created.</p></div></form>`,`<button class="button" data-close-overlay>Cancel</button><button class="button primary" type="submit" form="team-form">${team?"Save Team configuration":"Create Team"}</button>`,true);
